"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7253],{97381:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"defaultSidebar":[{"type":"link","href":"/VluxySF/docs/intro","label":"Introduction","docId":"intro","unlisted":false},{"type":"link","href":"/VluxySF/docs/WhyVluxySF","label":"Why VluxySF?","docId":"WhyVluxySF","unlisted":false},{"type":"link","href":"/VluxySF/docs/Installation","label":"Installation","docId":"Installation","unlisted":false},{"type":"link","href":"/VluxySF/docs/FolderSetup","label":"Folder Setup","docId":"FolderSetup","unlisted":false},{"type":"link","href":"/VluxySF/docs/Setup","label":"Starting the Library","docId":"Setup","unlisted":false},{"type":"link","href":"/VluxySF/docs/Fetching","label":"Fetching Sounds","docId":"Fetching","unlisted":false},{"type":"link","href":"/VluxySF/docs/SoundGroups","label":"SoundGroups and Volume","docId":"SoundGroups","unlisted":false},{"type":"link","href":"/VluxySF/docs/Preloading","label":"Preloading","docId":"Preloading","unlisted":false},{"type":"link","href":"/VluxySF/docs/Presets","label":"Presets and Jitter","docId":"Presets","unlisted":false},{"type":"link","href":"/VluxySF/docs/Cookbook","label":"Cookbook","docId":"Cookbook","unlisted":false},{"type":"link","href":"/VluxySF/docs/Warming","label":"Warming and Chilling","docId":"Warming","unlisted":false},{"type":"link","href":"/VluxySF/docs/Performance","label":"Performance and Memory","docId":"Performance","unlisted":false},{"type":"link","href":"/VluxySF/docs/Wrapping","label":"Wrapping Sounds","docId":"Wrapping","unlisted":false},{"type":"link","href":"/VluxySF/docs/HowItWorks","label":"How It Works","docId":"HowItWorks","unlisted":false}]},"docs":{"Cookbook":{"id":"Cookbook","title":"Cookbook","description":"Complete examples for common jobs. Each one assumes the library has been started and that client code waits for it with VluxySF.Startup.WaitUntilReady(). Swap the example sound names for your own.","sidebar":"defaultSidebar"},"Fetching":{"id":"Fetching","title":"Fetching Sounds","description":"Fetching builds a fresh Sound from the one you set up in Studio, with its properties, effects and SoundGroup. There are three ways to fetch, depending on what you need the sound for.","sidebar":"defaultSidebar"},"FolderSetup":{"id":"FolderSetup","title":"Folder Setup","description":"All of your sounds live in one place: a Configuration named SOUNDS inside ServerStorage.","sidebar":"defaultSidebar"},"HowItWorks":{"id":"HowItWorks","title":"How It Works","description":"You do not need this page to use the library, but it helps when you want to know what happens behind a fetch, what it costs, and why the library behaves the way it does when something goes wrong.","sidebar":"defaultSidebar"},"Installation":{"id":"Installation","title":"Installation","description":"VluxySF is installed with Wally, a package manager for Roblox, and synced into Studio with Rojo.","sidebar":"defaultSidebar"},"intro":{"id":"intro","title":"Introduction","description":"What is VluxySF?","sidebar":"defaultSidebar"},"Performance":{"id":"Performance","title":"Performance and Memory","description":"VluxySF is fast enough that you will rarely think about it. This page has the numbers, and the habits that keep sound memory low on phones and older devices.","sidebar":"defaultSidebar"},"Preloading":{"id":"Preloading","title":"Preloading","description":"A sound\'s audio has to download before it can be heard. The first time a sound plays, that can mean a short silence. Preloading downloads the audio ahead of time and keeps it loaded for the whole session, so the sound plays the moment you need it.","sidebar":"defaultSidebar"},"Presets":{"id":"Presets","title":"Presets and Jitter","description":"A preset is a function that adjusts a Sound as it is fetched. Pass one as the third argument of Fetch, TryFetch or OneShot to set a sound up the same way every time. It runs before the sound is parented.","sidebar":"defaultSidebar"},"Setup":{"id":"Setup","title":"Starting the Library","description":"VluxySF has to be started once on the server and once on each client. After that, every script can fetch sounds.","sidebar":"defaultSidebar"},"SoundGroups":{"id":"SoundGroups","title":"SoundGroups and Volume","description":"Every group Configuration directly under SOUNDS becomes a SoundGroup with the same name, and every sound inside it plays through that group. All the groups sit under one main SoundGroup, also named SOUNDS, in SoundService.","sidebar":"defaultSidebar"},"Warming":{"id":"Warming","title":"Warming and Chilling","description":"Warming builds a sound once, effects included, and keeps the ready-made Sound around. While it is warm, every Fetch of that sound clones the kept copy instead of building a new one. Chilling throws the kept copy away again.","sidebar":"defaultSidebar"},"WhyVluxySF":{"id":"WhyVluxySF","title":"Why VluxySF?","description":"Most Roblox games start out handling sound the same way, and most run into the same problems as they grow. This page walks through them, then shows what VluxySF does about each one.","sidebar":"defaultSidebar"},"Wrapping":{"id":"Wrapping","title":"Wrapping Sounds","description":"VluxySF.Fetch returns a plain Sound. If you want every fetch to give you your own class instead, with methods like FadeIn or SetLooped, use VluxySF.WithWrapper.","sidebar":"defaultSidebar"}}}}')}}]);